            "The app automatically falls back to ordinary listings on older firmware. Missing or unsupported modification dates remain blank; a blank date is not an error by itself. MAVLink FTP uses the telemetry connection and does not mount a USB drive. Remote file changes are separate from parameter writes; keep a backup before replacing or removing important files."),
        T(Configuration, "Parameters Editor",
            "Search, review, save/load and apply vehicle parameters, including pasted text edits.",
            "Load the intended vehicle's parameters and save a backup.|Find values in the grid or open the text editor and enter one name/value pair per line.|Use Apply modified to write reviewed changes, then read the Markdown progress and completion report.",
            "Check confirmed changes, skipped unknown names, invalid values and write failures separately. Baseline is the first received value in the current vehicle/firmware editing session, not a factory default. Refresh retains it; a new session after disconnect or vehicle change captures a new baseline. Hover its value for current FC value and any explicit metadata default; unavailable defaults remain Unknown. Reboot when the report requires it.",
            "The text editor accepts full-line and inline // comments and supported separators such as =. Invalid or unknown entries are reported rather than silently treated as successful writes. Open Parameter profiles from the parameter actions menu to create a named set from all current values, modified values or a comma/space-separated list of selected names. Snapshots include pending edits. Add a description and comma-separated tags, then Create new profile. Select a saved profile to review firmware/vehicle mismatch warnings and live/profile values; select compatible differences and Stage selected. Close profiles and use Apply modified only after reviewing the pending edits. Save details renames or updates metadata without replacing stored values; Duplicate creates a separate copy. Profiles also support confirmed deletion and JSON import/export; importing creates a new local profile and never overwrites an existing one."),
        T(Configuration, "CubeLan 8 Port Switch",
            "Read and edit the supported CubeLAN switch settings.",
            "Use Discover / read to obtain the current device configuration.|Review COS, COS priority, EEE, VLAN tagging and the membership matrix.|Export a backup, then use Apply and verify for the intended changes; Revert discards local edits.",
            "Check the verification result and network connectivity after applying.",
            "This editor does not expose PoE, port enablement, VLAN IDs, modes, authentication or editable labels. Do not infer unsupported settings from the displayed matrix.")
    ];

    private static SectionHelp T(string group, string title, string purpose, string steps,
        string verify, string note, string? url = null) =>
        new(group, title, purpose, steps.Split('|'), verify, note,
            new Uri(url ?? (group == Mandatory ? SetupDocs : group == Configuration
                ? "https://ardupilot.org/planner/docs/mission-planner-configuration-and-tuning.html"
                : PeripheralDocs)));

    public static UserDocument CreateDocument(SectionHelp topic)
    {
        var builder = new UserDocumentBuilder().Heading(topic.Title)
            .Paragraph(topic.Group + " / " + topic.Title)
            .Paragraph(topic.Purpose)
            .Heading("How to use this section", 3);
        foreach (var step in topic.Steps) builder.Bullet(step);
        builder.Heading("Verify the result", 3).Paragraph(topic.Verification)
            .Heading("Important details", 3).Note(topic.Note);
        if (topic.Group is Mandatory or Optional)
            builder.Paragraph("Available controls depend on the connected firmware and hardware. Refresh after reconnecting; a missing or disabled control is not evidence that a setting has been applied.");
        else if (topic.Group == Configuration)
            builder.Paragraph("Keep a backup before changing configuration. Editing or loading values locally is separate from applying them to the connected vehicle.");
        return builder.Build(topic.Title);
    }
}

public sealed record SectionHelp(string Group, string Title, string Purpose, string[] Steps,
    string Verification, string Note, Uri Documentation);
